<?php $beRoot=base_url('store/'.$settings->store_slug); ?>
<main class="be-commerce be-shell be-enquiry-page"><nav class="be-crumbs" aria-label="Breadcrumb"><a href="<?= $beRoot; ?>">Home</a><span>/</span><span>Start a conversation</span></nav><header class="be-page-heading"><div><span class="be-eyebrow"><?= $beCopy('enquiry_eyebrow'); ?></span><h1><?= $beCopy('enquiry_heading'); ?></h1><p><?= $beCopy('enquiry_intro'); ?></p></div></header>
<section class="garden-enquiry be-enquiry-form"><span class="be-eyebrow"><?= $beCopy('enquiry_form_eyebrow'); ?></span><h2><?= !empty($garden_request_received)?'Thank you for sharing.':$beCopy('enquiry_form_heading'); ?></h2>
<?php if($garden_request_received): ?><p role="status">Thank you. Your request has been received. The team will contact you to confirm the scope, price and availability.</p><a class="be-pill" href="<?= $beRoot; ?>"><?= $beCopy('shop_explore'); ?> ↗</a><?php else: ?><?php if($garden_request_error): ?><p role="alert" class="be-form-error"><?= htmlspecialchars($garden_request_error); ?></p><?php endif; ?><p>Preferred dates are requests and will be confirmed by the team.</p><form method="post" action="<?= htmlspecialchars($garden_request_url); ?>"><input type="hidden" name="<?= $this->security->get_csrf_token_name(); ?>" value="<?= $this->security->get_csrf_hash(); ?>"><input type="hidden" name="submission_ref" value="<?= htmlspecialchars($garden_request_key); ?>"><input type="hidden" name="service_id" value="<?= (int)($garden_requested_service->id ?? 0); ?>"><input type="hidden" name="product_id" value="<?= (int)($garden_requested_product->id ?? 0); ?>"><input name="website" tabindex="-1" autocomplete="off" hidden>
<?php if($garden_requested_service): ?><h3><?= htmlspecialchars($garden_requested_service->service_name); ?></h3><?php endif; ?><?php if(!empty($garden_requested_product)): ?><h3><?= htmlspecialchars($garden_requested_product->item_name); ?></h3><?php endif; ?>
<fieldset class="be-enquiry-kinds"><legend>What can we help with?</legend><?php foreach(['landscaping'=>$beValue('enquiry_project_type'),'maintenance'=>$beValue('enquiry_service_type')] as $mode=>$label):if(!mp_garden_has_mode($garden_profile,$mode))continue; ?><label><input type="radio" name="request_kind" value="<?= $mode; ?>" required <?= $this->input->post('request_kind')===$mode?'checked':''; ?>><span><?= htmlspecialchars($label,ENT_QUOTES,'UTF-8'); ?></span></label><?php endforeach; ?></fieldset>
<div class="be-enquiry-fields"><?php foreach(['name'=>'Your name','phone'=>'Phone','email'=>'Email (optional)','site_location'=>'Site location','preferred_date'=>'Preferred visit date (optional)','budget'=>'Budget (optional)'] as $key=>$label): ?><label><?= $label; ?><input type="<?= ['email'=>'email','phone'=>'tel','preferred_date'=>'date','budget'=>'number'][$key] ?? 'text'; ?>" name="<?= $key; ?>" <?= in_array($key,['name','phone','site_location'],true)?'required':''; ?> <?= $key==='budget'?'min="0" step="0.01"':''; ?> value="<?= htmlspecialchars((string)($this->input->post($key) ?? '')); ?>"></label><?php endforeach; ?></div><label>Project or service description<textarea name="description" rows="5" maxlength="4000" required placeholder="Your ideas, your space, and anything else we should know…"><?= htmlspecialchars((string)($this->input->post('description') ?? '')); ?></textarea></label><button type="submit" class="be-pill"><?= $beCopy('enquiry_send'); ?> <span>↗</span></button></form><?php endif; ?></section></main>
